local EFFECT_PATH_RIGHT = "Effect/prefab/ui_prefab/ui_tuya_right_effect.prefab"
local EFFECT_PATH_RIGHT2 = "Effect/prefab/ui_prefab/ui_tuya_right02_effect.prefab"

