function UICultivateEquipNodeMB:OnDestroy()
    if not isNull(self.rightEffectLoader) then
        self.rightEffectLoader:Release(true)
        self.rightEffectLoader = nil
    end
    if not isNull(self.leftEffectLoader) then
        self.leftEffectLoader:Release(true)
        self.leftEffectLoader = nil
    end
    self:StopCo()
    self.controller = nil--luabehaviour 中CSharp对象 self:Delete()
    self:Delete()
    self = nil
end


