function UICultivateEquipNodeMB:RefreshUI(equipDojo, isDisableLevel, isDisablePlus)
    local isOwnEquip = equipDojo ~= nil and type(equipDojo) ~= "function"  and next(equipDojo) ~= nil

    KTool.SetActive(self.EquipIcon, isOwnEquip)
    KTool.SetActive(self.QualityImage, isOwnEquip)
    KTool.SetActive(self.PlusImage.gameObject, not isOwnEquip and not isDisablePlus)
    KTool.SetActive(self.LevelBgImage, isOwnEquip and not isDisableLevel)

    if isOwnEquip then
        local refId = equipDojo.equipmentId
        ---@type GoodsVo
        local goodsVo = goodsConfMgr:GetGoodsVoById(refId)
        CfUtils.FillImage(self.EquipIcon, goodsVo.photoPath, false)

        self:RefreshLevel(equipDojo.level)

        CfUtils.FillImage(self.QualityImage, GetEquipRareIconPath(goodsVo.quality), false)

        ---@type EquipVo
        local equipVo = cardConfMgr:GetEquipVoById(refId)
        EquipUtils.SetEquipPartBgScale(self.EquipIconBG, equipVo.part)
    end

end

---RefreshSelectState
---刷新选择状态
---@param isSelect boolean
function UICultivateEquipNodeMB:RefreshSelectState(isSelect)
    KTool.SetActive(self.SelectImage.gameObject, isSelect)
end

function UICultivateEquipNodeMB:RefreshSuitActiveState(isActive, cb, part)
    if self.animator == nil then return end

    self:StopCo()
    self.playAni = true
    self.co = cs_coroutine.start(function()

        xTry(function()
            --Events.Broadcast(Constants.EventNames.UICultivateEquipUpdateCoreCanvasShow, true)
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.2))

            if isActive then
                local isRightEquipNode = part % 2 == 0
                if self.rightEffect == nil then
                    self.rightEffect, self.rightEffectLoader = self:AddEffect(isRightEquipNode and EFFECT_PATH_RIGHT2 or EFFECT_PATH_RIGHT)
                else
                    KTool.SetActive(self.rightEffect.gameObject, true)
                end
                cs_coroutine.yield_return(self.animator:PlayAndWait(MOTION_NAME_ENTER))

                if self.leftEffect == nil  then
                    self.leftEffect, self.leftEffectLoader = self:AddEffect(EFFECT_PATH_LEFT)
                    self.leftEffect.transform.localScale = Vector3.New(-1, 1, 1)
                    ---@type UnityEngine.RectTransform
                    local rt = KTool.GetComponent(self.leftEffect.gameObject, RectTransformType)
                    local anchoredPosition = rt.anchoredPosition
                    rt.anchoredPosition = Vector3.New(2.1, anchoredPosition.y, 0)
                else
                    KTool.SetActive(self.leftEffect.gameObject, true)
                end
                KTool.SetActive(self.rightEffect.gameObject, false)
            else
                if self.leftEffect then
                    KTool.SetActive(self.leftEffect.gameObject, false)
                end
                cs_coroutine.yield_return(self.animator:PlayAndWait(MOTION_NAME_END))
            end
            Events.Broadcast(Constants.EventNames.UICultivateEquipUpdateCoreCanvasShow, false)
            self.playAni = nil
            if cb then
                cb()
            end
        end, function()
            printError("%s", debug.traceback())
        end)

    end)

end

function UICultivateEquipNodeMB:RefreshLevel(level)
    self.EquipLevelText.text = level
end

function UICultivateEquipNodeMB:RefreshPosition(isActive, part)
    local isRightEquipNode = part % 2 == 0
    local posX
    if isActive then
        posX = isRightEquipNode and 183 or -146
    else
        posX = isRightEquipNode and 201.1498 or -169.35
    end

    local rt = self.controller.gameObject:GetComponent(typeof(RectTransformType))
    local anchoredPosition = rt.anchoredPosition
    rt.anchoredPosition = Vector3.New(posX, anchoredPosition.y, 0)
end

function UICultivateEquipNodeMB:StopCo()
    if self.co then
        cs_coroutine.stop(self.co)
        self.co = nil
    end
end

function UICultivateEquipNodeMB:AddEffect(effectPath)
    local go, loader = GameUtils.LoadBundleSync(effectPath, self.controller.gameObject)
    -- if go == nil then
    --     go.transform.localPosition = Vector3.zero
    --     go.transform.localRotation = Quaternion.identity
    --     go.transform.localScale = Vector3.one
    -- end
    KTool.GetOrAddComponent(go, CanvasType)
    return go, loader
end

